True def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(size, separators):
        out, start = [], 0
        for i in separators:
            if start < i:
                out.append((start, i))
            start = i + 1
        if start < size:
            out.append((start, size))
        return out

    rows, cols = segments(h, sep_rows), segments(w, sep_cols)
    bg = next(grid[r][c] for r in range(h) for c in range(w)
              if r not in sep_rows and c not in sep_cols)
    result = [[bg for _ in cols] for _ in rows]
    for i, (r0, r1) in enumerate(rows):
        for j, (c0, c1) in enumerate(cols):
            if sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)) >= 2:
                result[i][j] = 1
    return result
